{"command":"@'
import re, os, json
root = r'e:/PVE/game/dzsj/scripts/vscripts'
link = set()
add = []
for dirpath, _, filenames in os.walk(root):
    for fn in filenames:
        if not fn.endswith('.lua'): continue
        path = os.path.join(dirpath, fn)
        try:
            data = open(path, 'r', encoding='utf-8').read()
        except Exception:
            data = open(path, 'r', encoding='utf-8', errors='ignore').read()
        for m in re.finditer(r'LinkLuaModifier\(\s*["\"]([^"\"]+)["\"]', data):
            link.add(m.group(1))
        # AddNewModifier(..., "modifier_name" , ...)
        for m in re.finditer(r'AddNewModifier\([^\)]*?["\"]([^"\"]+)["\"]', data):
            add.append((m.group(1), path))
        # ApplyModifier ? (not used)

# built-in mods known to be safe in this project
builtin = set([
    'modifier_invulnerable','modifier_phased','modifier_rooted','modifier_unselectable','modifier_no_healthbar',
    'modifier_stunned','modifier_knockback','modifier_knockback_no_anim','modifier_illusion','modifier_kill',
    'modifier_animation','modifier_animation_translate','modifier_animation_translate_permanent','modifier_animation_freeze',
    'modifier_animation_freeze_stun','modifier_item_ultimate_scepter','modifier_tiny_tree_grab_visual',
    'modifier_tiny_tree_grab',
])
missing = {}
for name, path in add:
    if name in link or name in builtin:
        continue
    # also skip dynamic variables like self.modifier_sp or TAUNT_MODIFIER; but we only captured string literal
    missing.setdefault(name, set()).add(path)

print('Missing literals:', len(missing))
for name in sorted(missing):
    print(name)
    for path in sorted(missing[name]):
        print('  ', path)
'@ | python -"}
